document.getElementById('notification-form').addEventListener('submit', function(event) {
    event.preventDefault();

    const form = event.target;
    const formData = new FormData(form);
    const preference = formData.get('notification-preference');
    const errorMessage = document.getElementById('error-message');
    const statusMessage = document.getElementById('status-message');

    // Reset messages
    errorMessage.textContent = '';
    statusMessage.textContent = '';
    statusMessage.className = 'status-message';

    if (!preference) {
        errorMessage.textContent = 'Error: Please select a notification preference.';
        // Focus the first radio button if none are selected
        form.querySelector('input[type="radio"]').focus();
        return;
    }

    // Simulate success
    statusMessage.textContent = `Preference saved: ${preference.charAt(0).toUpperCase() + preference.slice(1)}`;
    statusMessage.classList.add('success');
});

// Clear error message when a radio button is selected
document.querySelectorAll('input[type="radio"]').forEach(radio => {
    radio.addEventListener('change', () => {
        const errorMessage = document.getElementById('error-message');
        errorMessage.textContent = '';
    });
});

